css:
.loader { display: flex; flex-direction: column; align-items: center; gap: calc(var(--loader-size) * .09); width: var(--loader-size); }
.loader .arrow { position: relative; width: calc(var(--loader-size) * .09); height: calc(var(--loader-size) * .32); border-radius: 9999px; background: var(--loader-color); animation: twDown calc(var(--loader-speed) * 1.5) ease-in-out infinite; }
.loader .arrow::after { content: ''; position: absolute; bottom: calc(var(--loader-size) * -.05); left: 50%; width: calc(var(--loader-size) * .22); height: calc(var(--loader-size) * .22); margin-left: calc(var(--loader-size) * -.11); border-right: calc(var(--loader-size) * .09) solid var(--loader-color); border-bottom: calc(var(--loader-size) * .09) solid var(--loader-color); border-radius: calc(var(--loader-size) * .03); transform: rotate(45deg); }
.loader .track { width: 100%; height: calc(var(--loader-size) * .08); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color) 20%, transparent); overflow: hidden; }
.loader .track i { display: block; width: 100%; height: 100%; border-radius: 9999px; background: var(--loader-color); transform-origin: left center; animation: twFill calc(var(--loader-speed) * 1.5) ease-in-out infinite; }
@keyframes twDown { 0%, 100% { transform: translateY(-14%); opacity: .5; } 55% { transform: translateY(10%); opacity: 1; } }
@keyframes twFill { 0% { transform: scaleX(0); } 100% { transform: scaleX(1); } }
